insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 1, 'The digest counts, for each module, the exports that read a date against today. Which module has the most of them?', '["qualityAssurance, with 7.", "documentControl, which exports 14 functions.", "isoCompliance, with 10 of them.", "complianceStatus, with 4."]'::jsonb, 2, 'The export table prints 10 for isoCompliance, 7 for qualityAssurance and 4 each for complianceStatus, documentControl and auditManagement. The 14 is documentControl''s count of exported functions, which is a different column.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 2, 'Every figure in the digest is stated as true at 2026-10-15. What makes that statement safe to make?', '["Every call that reads a date against today is passed that one date, and no line comes from a call that read the machine clock.", "The digest was generated on 2026-10-15, so the machine clock and the as-of date agreed on the day it ran.", "Each module stores the date it was last run with, and reads it back on the next call.", "The records themselves carry 2026-10-15 as a field, which the engine copies into each status."]'::jsonb, 0, 'The as-of date is an argument. The generator refuses to print a line from a call that did not pass it, so the same inputs give the same answers on any machine on any day.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 3, 'At the as-of date, daysUntil of 2026-09-30 prints -15. What does the minus sign tell a reader?', '["An unreadable date, reported as -15.", "The day is already behind the as-of date, by 15 days.", "15 days still to go before that date.", "The date falls in a month the calendar pulls back, and the sign marks the pull."]'::jsonb, 1, 'A positive count is a day still ahead, as 2026-11-30 reads 46. A negative count is a day already gone, and the as-of date itself reads 0. A refused input prints none, never a number.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 4, 'The calendar is given the as-of date with a time late in the evening and an offset of fourteen hours written after it. What does parseDateOnly make of it, and what count does daysUntil give?', '["null, with a count of none.", "The day that instant falls on in the reading machine''s own time zone, so the count depends on where it is read.", "2026-10-15 as an instant late in the evening, so its count is a fraction of a day short of the plain date.", "2026-10-15, with a count of 0."]'::jsonb, 3, 'parseDateOnly reads the leading YYYY-MM-DD and nothing after it, at local midnight. The row prints 2026-10-15 and 0, the same as the plain date, so the answer is the same in Lagos and in Houston.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 5, 'Which of these inputs has the correct YYYY-MM-DD shape and is still refused by parseDateOnly?', '["15/10/2026, a day written day first.", "2026-02-30, a day February does not have.", "2027-02-28, the last day of a short month.", "2026-11-30, a month end with thirty days."]'::jsonb, 1, '2026-02-30 is shaped correctly and names a day that does not exist, so it prints null. 15/10/2026 is also refused, for its shape. 2027-02-28 reads 136 and 2026-11-30 reads 46.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 6, '15/10/2026 names a real day. Why does the calendar still print null for it?', '["The calendar reads only the YYYY-MM-DD order, and it refuses to guess which of the numbers is the month.", "The day it names is the as-of date itself, and the calendar refuses to count a date against itself.", "It is read as the fifteenth month of 2026, a month the calendar cannot build.", "It is read correctly as a day, and only its daysUntil is withheld as none."]'::jsonb, 0, 'A real day written in the order a person in Lagos might write it is still refused. A guess would put a date on the record that nobody chose, and every status derived from it would carry the guess.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 7, 'REG-2026-013, the waste consignment register, has no due date and no expiry. What status does it read?', '["On track, because with no date on the record nothing has been missed so far and nothing is late.", "Overdue, a blank date read as one already passed.", "No date set, with a reason saying nothing can fall due.", "Draft, because an obligation with no dates is treated as one still being set up."]'::jsonb, 2, 'explainStatus gives "No due date or expiry date has been set, so nothing can fall due." The gap is shown with its own status word, and in the sorted register it sits tenth.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 8, 'A published document in the IKORO library has the text tbc typed where its review date belongs. What review state does it read?', '["Review overdue, because an unreadable date is counted as a date long past.", "Not in force, because the calendar refuses the date and the document with it.", "Review scheduled, because tbc is read as a date far enough ahead to be outside the window.", "No review scheduled"]'::jsonb, 3, 'tbc is no date, so the document is in force with nothing scheduled for it. The library shows the gap to the reader instead of hiding it behind a date nobody entered.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 9, 'Which module refuses to produce an answer when the date it is given as today cannot be read?', '["documentControl, whose reviewState stops and names the bad date.", "complianceStatus, whose deriveStatus throws a RangeError.", "qualityAssurance, whose isNcrOverdue throws for an open NCR.", "All three, each with its own error message."]'::jsonb, 1, 'deriveStatus throws RangeError: deriveStatus needs a valid date for today. That refusal is owner decision AS15 Q1. The other two modules answer instead of refusing.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 10, 'documentControl.reviewState is asked about a published document whose review date is 2020-01-06, with an unreadable Date as today. It returns Review scheduled. What does that answer say about the document?', '["Nothing that can be trusted, because an unreadable today is refused by complianceStatus alone.", "That the review has been booked for a date the engine chose in place of the unreadable one.", "That the document is in force and its review date of 2020-01-06 lies ahead.", "That the document has been reviewed, because a passed review date with no today is read as done."]'::jsonb, 0, 'The digest records this as a held limit. reviewState answers as though nothing were due, and the course teaches it as a limit and never as a figure.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 11, 'An open NCR was due 2020-01-06. qualityAssurance.isNcrOverdue is handed a today it cannot read. What is its answer?', '["true, because 2020-01-06 is before any date the NCR could be read against.", "It throws a RangeError, as deriveStatus does.", "false", "null, the value the calendar gives for an unreadable date."]'::jsonb, 2, 'false says the NCR is not overdue, which no reader can rely on here. deriveStatus is the one export that throws; this answer is recorded in SECTION 2 as a limit.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 12, 'documentControl.reviewState is passed today as the STRING 2026-10-15. What happens?', '["It parses the string at local midnight and returns the same review state it gives for the Date.", "It returns Review scheduled.", "It returns Not in force.", "It throws TypeError: d.getFullYear is not a function."]'::jsonb, 3, 'The as-of date has to be passed as a date. A string that spells the right day is still the wrong kind of value, and the call fails.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 13, 'What does owner decision AS15 Q1 state?', '["An unreadable today makes every module answer as though nothing were due.", "An unreadable today makes deriveStatus throw.", "A today passed as a string is read at local midnight.", "An unreadable record date reads as today."]'::jsonb, 1, 'Q1 is the refusal the digest prints for deriveStatus: RangeError: deriveStatus needs a valid date for today. The two other modules answering as though nothing were due is a held limit, and a string today makes reviewState throw a TypeError.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 14, 'The panel lets you move the as-of date. When you move it, statuses change. What was edited on the records in between?', '["Each record''s status field, rewritten by the panel.", "Each record''s due date, shifted by the panel.", "Nothing. The same records read against another date give other statuses.", "The lead time on each record, shortened by the panel."]'::jsonb, 2, 'That is what derived means in this course. A status is never typed, so moving the date back to 2026-10-15 makes every row match the digest again.'),
  ('compliance', 'beginner', 'module', 'm01-what-the-register-derives', 15, 'The digest''s header says in what form it prints every figure. Which form is that?', '["Whole numbers: day counts, counts, and percents the engine has already rounded.", "Days and fractions of a day, so a late evening time reads short of the plain date.", "Working days, so a weekend that falls between two dates is left out of a count.", "Whole weeks, with each day count rounded to the nearest week before it prints."]'::jsonb, 0, 'The header reads: every figure is a whole number, days from daysUntil and ages, counts, and percents the engine has already rounded. 2026-11-30 reads 46 and 2027-02-28 reads 136, and the lessons quote those figures as printed.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 1, 'REG-2026-005, the radioactive source licence, is Active with a due date of 2026-12-31 and an expiry of 2026-09-30. What does it read at the as-of date of 2026-10-15?', '["Overdue, at -15.", "Expired, with a days until of -15.", "On track, counted to 2026-12-31.", "Due soon, counted to 2026-12-31."]'::jsonb, 1, 'The next action date is the earlier of the due date and the expiry, here 2026-09-30. A passed expiry gives Expired, and explainStatus says "The permit expired 15 days ago."'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 2, 'The digest varies REG-2026-005 one field at a time. Which single variant makes the licence read Overdue?', '["The expiry removed.", "The expiry moved out to 2027-09-30.", "The lifecycle set to Archived, a word the lifecycle list does not have.", "The due date moved to 2026-10-01 with no expiry."]'::jsonb, 3, 'That variant reads Overdue at -14. Removing the expiry or moving it out leaves the licence On track, and Archived leaves it Expired at -15. A passed due date gives Overdue; a passed expiry gives Expired.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 3, 'REG-2026-005 is given the lifecycle word Archived, which complianceStatus.LIFECYCLES does not hold. What does it read?', '["Not applicable, because an unknown lifecycle is treated as one that does not bind the operator.", "Draft, the lifecycle a record falls back to until somebody sets it.", "Expired, at -15, the same as the licence as recorded.", "A refusal naming Archived as unknown."]'::jsonb, 2, 'Only Draft, Superseded and Not applicable switch the countdown off. A word outside the four leaves the dates in charge, and the passed expiry still gives Expired.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 4, 'Set REG-2026-005''s lifecycle to Superseded and change nothing else. It reads Superseded, and its days until still prints -15. Why is the count still printed?', '["The expiry is still on the record, so the count is printed, and the status ignores it because the lifecycle is read first.", "The engine reports how late the licence was at the moment it was superseded, for the audit trail.", "Superseded is ranked as a kind of Expired, and the count shows how far past expiry it is.", "The count is left over from before the change and will clear on the next save."]'::jsonb, 0, 'The lifecycle is checked before any date. The lapsed expiry that makes the recorded licence the worst row does not decide this variant''s status, and the date stays on the record.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 5, 'REG-2026-001, the produced water discharge permit, has a due date of 2027-03-31 and an expiry of 2026-11-20. What status does it read at 2026-10-15, and which date drives it?', '["On track, driven by 2027-03-31.", "Due soon, driven by 2027-03-31.", "Expired, driven by the expiry of 2026-11-20, because a permit with an expiry on the record reads Expired.", "Due soon, driven by the expiry of 2026-11-20."]'::jsonb, 3, 'The next action date is the earlier of the two dates, 2026-11-20, and it is inside the lead time recorded for the permit. The due date of 2027-03-31 is the same date REG-2026-004 counts to, and that row reads On track.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 6, 'REG-2026-009, the original environmental impact approval, has a due date of 2025-01-06 and a days until of -647. Why does it not read Overdue?', '["Its due date is too far behind the as-of date to count, and the engine stops counting after a year.", "Its lifecycle is Superseded, so it is not tracked against a date.", "It is a One-off, and a passed One-off reads Compliant.", "A later expiry cancels the passed due date."]'::jsonb, 1, 'explainStatus gives "Lifecycle is Superseded, so it is not tracked against a date." The day count is still printed because the date is still on the record.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 7, 'summarise prints an attention count of 5 for the IKORO register. Which statuses does that count add together?', '["Expired, Overdue and No date set.", "Expired and Overdue only.", "Expired, Overdue and Due soon.", "Due soon and On track."]'::jsonb, 2, 'complianceStatus.ATTENTION_STATUSES holds Expired, Overdue and Due soon. At IKORO those counts are 1, 2 and 2, and the attention count is 5.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 8, 'REG-2026-007 and REG-2026-002 are both Overdue. Why does byUrgency put REG-2026-007 above REG-2026-002?', '["Its next action date, 2026-09-01, is the nearer of the two.", "Its code sorts ahead of REG-2026-002 once the leading digits are read as a number.", "It is a One-off, and a One-off sorts ahead of a Monthly return with the same status.", "Its regime is Health & Safety, which the register ranks above Reporting."]'::jsonb, 0, 'byUrgency sorts by the worst status first, then by the nearest next action date. REG-2026-007 carries 2026-09-01 and REG-2026-002 carries 2026-10-10.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 9, 'REG-2026-007''s next action date, 2026-09-01, is earlier than REG-2026-005''s, 2026-09-30. Why does REG-2026-005 still sort first?', '["REG-2026-005 has the larger negative count, and the register sorts the most negative count to the top.", "Licences sort above notifications in the register, whatever their dates.", "REG-2026-007 has no filing, and an unfiled row sorts after a row that has one.", "Expired ranks above Overdue, and the status decides the order before the date does."]'::jsonb, 3, 'In complianceStatus.STATUS_SEVERITY Expired is first and Overdue second. byUrgency reads the status first and uses the date only among rows with the same status.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 10, 'REG-2026-003, the quarterly flare and venting return, was last filed 2026-07-28 and is due 2026-10-31. It reads On track. What does its reason say about that filing?', '["It counts for the current period, and the return is On track until its next due date.", "It was filed late, so the return cannot read Compliant until the next period.", "It was for an earlier period, so nothing has been filed for this one yet.", "It is too old to read, so the engine treats the return as never filed."]'::jsonb, 2, 'The reason reads "Due in 16 days. The last filing (2026-07-28) was for an earlier period, so nothing has been filed for this one yet." On track says there is time to do work that is still to do.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 11, 'REG-2026-008, the host community development report, reads Compliant. What makes it Compliant where REG-2026-003 reads On track?', '["Its last filing, 2026-08-05, falls inside the period it is in now.", "Its due date is further ahead, and a row far enough from its due date reads Compliant.", "It is a Semi-annual obligation, and every Semi-annual row with a filing reads Compliant.", "Its lead time is not set, so it has no warning window to fall into."]'::jsonb, 0, 'Compliant says the obligation has been met for the period it is in. REG-2026-003 has a filing too, but it belongs to an earlier period.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 12, 'Which owner decision separates On track from Compliant?', '["AS15 Q1: an unreadable today makes deriveStatus throw.", "AS15 Q2: evidence counts towards Compliant only for the current period.", "AS15 Q2: any filing on the record counts towards Compliant, whenever it was made.", "No decision: the lead time alone decides, and a row outside its window reads Compliant."]'::jsonb, 1, 'A filing made for last quarter says nothing about this quarter. Q1 is the unreadable today rule from module one, and a row outside its window with nothing filed for the period reads On track.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 13, 'On track sits fourth in complianceStatus.STATUS_SEVERITY and Compliant fifth. What do the two IKORO On track rows have that the two Compliant rows do not?', '["A due date that has already passed.", "An expiry date on the record.", "A lifecycle other than Active.", "Nothing filed for the period they are in now."]'::jsonb, 3, 'REG-2026-003 and REG-2026-004 each give the reason that the last filing was for an earlier period, so nothing has been filed for this one yet. REG-2026-008 was filed inside its period and REG-2026-006 is a filed One-off. All four are Active with no expiry, and only REG-2026-006''s due date has passed.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 14, 'The digest''s variant sets REG-2026-005''s lifecycle to Superseded. Of these summarise counts, which one would lose the licence?', '["Overdue", "Expired", "No date set", "Not applicable"]'::jsonb, 1, 'As recorded the licence is the one Expired row. With the lifecycle Superseded it reads Superseded, so it leaves the Expired count and joins the Superseded one.'),
  ('compliance', 'beginner', 'module', 'm02-an-obligations-status', 15, 'complianceStatus.LIFECYCLES holds four words. Which of them leaves an obligation counted down against its dates?', '["Active", "Draft", "Superseded", "Not applicable"]'::jsonb, 0, 'For Draft, Superseded and Not applicable the lifecycle is the status, and explainStatus says the record is not tracked against a date. An Active obligation is counted down.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 1, 'REG-2026-003, the quarterly flare and venting return, is due 2026-10-31, 16 days after the as-of date. Its recorded lead time is 14. Given a lead time of 17 and nothing else changed, what does it read?', '["On track, because the due date and the as-of date have not moved.", "Overdue, because the window now reaches back past the as-of date.", "Due soon", "On track, because the recorded lead time of 14 wins over a new one."]'::jsonb, 2, 'The digest prints 17 as Due soon. Only the lead time changed, and that alone turned On track into Due soon: the window now reaches the 16 days that remain.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 2, 'In the digest''s lead time table for REG-2026-003, what is the largest lead time that still leaves the return On track?', '["15", "14", "16", "0"]'::jsonb, 0, 'The rows print 14 On track, 15 On track and 16 Due soon. 14 is the lead time on the record, which is not the largest in the table that leaves it On track.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 3, 'REG-2026-003 has 16 days to its due date. With a lead time of 16, the same number, what does it read, and what does that say about the edge of the window?', '["On track, so the edge sits outside the window.", "On track, because the window opens on the day after the lead time is reached.", "Due soon only on the as-of date itself.", "Due soon, so the edge belongs inside the window."]'::jsonb, 3, 'The digest prints 15 On track and 16 Due soon. A lead time equal to the 16 days that remain puts the return inside its window, and the row reads Due soon.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 4, 'REG-2026-003 is given the word ''ten'' as its lead time. What does it read, and where does its window come from?', '["On track, a word read as no window.", "Due soon, from DEFAULT_LEAD_TIME_DAYS.", "Due soon, from reading ''ten'' as the number it spells.", "A refusal, since it is not a number."]'::jsonb, 1, 'An unusable lead time is replaced by DEFAULT_LEAD_TIME_DAYS. The rows for null, the empty string, -5, ''ten'' and a field left out all read Due soon, the status the return carries with the default window.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 5, 'REG-2026-003 is given a lead time of 0. It reads On track. What does that row show?', '["Zero is read as missing, and the default applies.", "Zero is refused and the old status is kept.", "Zero is a usable lead time, meaning no advance warning at all.", "Zero switches the obligation off, as Draft does."]'::jsonb, 2, 'A null, an empty string, a negative number and a word all read Due soon because the default applies to them. 0 reads On track, so the engine is applying the 0 it was given.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 6, 'A negative lead time, -5, is typed on the flare return''s record. Which status follows?', '["Due soon, because a negative lead time is not a usable one and the default applies.", "On track, because a negative window opens after the due date and is not open yet.", "Overdue, because a negative lead time reads the due date as five days passed.", "On track, the status it carries with a lead time of 0."]'::jsonb, 0, 'The digest prints -5 as Due soon. With no usable lead time the engine uses DEFAULT_LEAD_TIME_DAYS, and a negative number is not usable.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 7, 'REG-2026-012, the annual concession rental, is Due soon at 25 days. Its reason names a lead time. What is recorded as its lead time on the register?', '["The same window the reason names, entered when the obligation was set up.", "Nothing, because the reason is only shown when a lead time has been typed.", "The lead time of the discharge permit, copied across by the Financial regime.", "null"]'::jsonb, 3, 'The register prints null. The window in the reason is DEFAULT_LEAD_TIME_DAYS, and the reason says so: "inside the default" window, with "(none is set for this obligation)".'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 8, 'Two Due soon reasons name a window. Which words tell a reader that REG-2026-001''s window was chosen on the record?', '["\"inside the default\"", "\"set for this obligation\"", "\"(none is set for this obligation)\"", "\"nothing further is due\""]'::jsonb, 1, 'REG-2026-001''s reason names the lead time "set for this obligation". REG-2026-012''s names the default window and adds "(none is set for this obligation)", so a chosen window and a supplied one can be told apart without opening either record.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 9, 'periodStart steps one frequency back from a due date of 2026-10-31. Where does the Quarterly period start?', '["2026-07-28", "2026-10-10", "2026-07-31", "2026-08-05"]'::jsonb, 2, 'Three months back from the end of October is the end of July, which has a thirty-first. 2026-07-28 is the flare return''s last filing, which falls before that start.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 10, 'For a due date of 2026-10-31, which frequency''s current period starts on 2026-04-30?', '["Quarterly", "Annual", "Biennial", "Semi-annual"]'::jsonb, 3, 'Semi-annual steps six months back and April has no thirty-first, so the start is pulled back to 2026-04-30. Quarterly starts 2026-07-31, Annual 2025-10-31 and Biennial 2024-10-31.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 11, 'REG-2026-004, the annual monitoring report, is due 2027-03-31 and its period starts 2026-03-31. Its last filing is dated 2026-03-30. What is its status, and what would one day later on the filing make it?', '["On track as recorded, and Compliant with the filing dated 2026-03-31.", "Compliant as recorded, because a filing at the end of March covers a report due at the end of March.", "On track either way, because the filing date is not what decides the status here.", "Overdue as recorded, and On track with the filing dated 2026-03-31."]'::jsonb, 0, 'Dated 2026-03-30 the filing belongs to the earlier period. Dated 2026-03-31, the first day of the period, it counts, and the digest prints status Compliant. The first day of the period is inside the period.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 12, 'REG-2026-002, the monthly water quality return, was due 2026-10-10 and was last filed 2026-09-09. Its period starts 2026-09-10. What does it read, and why?', '["Compliant, a day early is close enough.", "Overdue, because that filing counts for the period before.", "On track, because a monthly return has a filing inside the last month.", "Due soon, the filing moved the due date on."]'::jsonb, 1, 'The filing falls before the period start, so it discharged the period before. The return for the current period is late, and the reason says "The due date passed 5 days ago."'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 13, 'REG-2026-012, the annual concession rental, was last paid 2025-11-03, and its current period starts 2025-11-09. Does that payment count for the current period?', '["Yes. A payment in the same month as the period start counts for that period.", "Yes. An annual payment counts for any period that ends within a year of it.", "No. A payment counts only once the next due date has been rolled forward.", "No. It falls before the period start, so it covered the period before."]'::jsonb, 3, 'periodStart for the rental prints 2025-11-09, and the payment of 2025-11-03 is earlier, so nothing has been paid for this period. A filing counts when it is on or after the period start, as REG-2026-008''s filing of 2026-08-05 does against 2026-07-31 with no roll.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 14, 'REG-2026-008 is Semi-annual, due 2027-01-31, with its period starting 2026-07-31. Its last filing is 2026-08-05. What does it read?', '["On track, because every filing is read as belonging to an earlier period.", "On track, because a Semi-annual period is counted from the filing date.", "Compliant", "Due soon, because a filing inside the period opens the warning window."]'::jsonb, 2, 'The filing on 2026-08-05 is on or after the period start of 2026-07-31, so the period is discharged. Of the five IKORO filings read against their periods, it is the only one that counts.'),
  ('compliance', 'beginner', 'module', 'm03-lead-time-and-the-current-period', 15, 'In Document Control, which state plays the part Due soon plays in the register, and which constant sets its window?', '["Review scheduled, with complianceStatus.DEFAULT_LEAD_TIME_DAYS.", "Review due soon, with documentControl.REVIEW_LEAD_DAYS.", "Review due soon, with documentControl.DEFAULT_REVIEW_PERIOD_MONTHS.", "Review overdue, with each document''s own lead time."]'::jsonb, 1, 'OPS-PLA-0002, the terminal emergency response plan, has its next review on 2026-11-02, 18 days after the as-of date, and reads Review due soon. DEFAULT_REVIEW_PERIOD_MONTHS is a review period in months.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 1, 'REG-2026-002 was due 2026-10-10 and is filed late on 2026-10-14. What next due date does the Regulatory Compliance app roll the return to?', '["2026-11-14", "2026-11-10", "2026-10-14", "2026-11-09"]'::jsonb, 1, 'The app passes the due date to rollForward: rollForward(2026-10-10, Monthly) = 2026-11-10. The same call on the filing date would give 2026-11-14, the date the app does not use.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 2, 'Why does the app roll a monthly return forward from the date that was due and never from the filing date?', '["A roll from the filing would land on a month end the calendar has to pull back, and the pull is avoided.", "The filing date is not stored on the record.", "Rolling from the filing warns too soon.", "The next due date then follows the old one, whatever day the filing came in."]'::jsonb, 3, 'The digest prints rollForward(2026-10-10, Monthly) = 2026-11-10. The same call on the filing date would give 2026-11-14, so a roll from the filing would move the schedule later with each late filing.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 3, 'Once the late filing of REG-2026-002 is recorded and its due date rolled, what does the return read?', '["Due soon, with a next action date of 2026-11-10 and 26 days to go.", "Compliant, because the filing on 2026-10-14 counts for the current period.", "Overdue, because the filing came after the date that was due.", "On track, counted to 2026-11-14."]'::jsonb, 0, 'The rolled row''s period starts 2026-10-10 and the filing is on or after it, so the filing counts. The row is still Due soon because 26 days is inside the default window, and the lead time is asked about first.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 4, 'The same rolled REG-2026-002 row is given lead_time_days 0. What does it read?', '["Due soon, because the default window still applies when the lead time is 0.", "On track, because nothing has been filed for the period that starts 2026-11-10.", "Compliant: \"Last filed 2026-10-14, next due in 26 days.\"", "Overdue, a lead time of 0 leaves no time."]'::jsonb, 2, 'With lead_time_days 0 no window is open, so the next question deriveStatus asks is about the filing. The filing counts for the current period, and the row reads Compliant.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 5, 'What do the two statuses of the rolled REG-2026-002 row, Due soon with its window open and Compliant with lead_time_days 0, show about deriveStatus?', '["It asks about the filing first.", "It asks about the lead time window before it asks about the filing.", "It reads the lead time only for a row never filed.", "It treats a lead time of 0 as missing."]'::jsonb, 1, 'The digest states it: deriveStatus asks whether the next action date is inside the lead time before it asks about the filing. The open window is what keeps the row at Due soon.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 6, 'rollForward is given a due date of 2026-08-31 and the frequency Monthly. What next due date does it give?', '["2026-09-30", "2026-10-01", "2026-11-30", "2026-10-31"]'::jsonb, 0, 'September has no thirty-first, so the date is pulled back to the last day of that month. The rule never pushes a date into the next month. 2026-11-30 is the Quarterly roll.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 7, 'From the same due date of 2026-08-31, which frequency keeps the thirty-first on its next due date?', '["Annual, which lands on 2027-08-31.", "Quarterly, which lands on 2026-11-30.", "Semi-annual, which lands on 2027-02-28.", "Monthly, landing on 2026-09-30."]'::jsonb, 0, 'August has a thirty-first, so the Annual and Biennial rolls keep it: 2027-08-31 and 2028-08-31. November, February and September are shorter, so those rolls are pulled back.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 8, 'A due date on the leap day 2028-02-29 is rolled forward by Annual. What does rollForward give?', '["2028-02-29", "2027-02-28", "2029-02-28", "none"]'::jsonb, 2, '2029 has no twenty-ninth of February, so the date is pulled back to that month''s last day. 2027-02-28 is the Semi-annual roll from 2026-08-31, and none is what rollForward gives for One-off and Other.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 9, '2026-01-31 rolled Monthly gives 2026-02-28. Where does the roll after that land?', '["2026-03-31", "2026-02-28", "2026-04-28", "2026-03-28"]'::jsonb, 3, 'Each roll starts from the date it is given. A date pulled back to the end of a short month rolls on from that day of the month, so the schedule does not return to the thirty-first on its own. 2026-04-28 is the roll after 2026-03-28.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 10, 'rollForward is given the frequency One-off. What does it return, and what does that none mean?', '["The due date it was given, so a One-off stays due on the same day each year.", "A refusal naming One-off as a frequency the calendar cannot step by.", "The date one year on, the interval the engine assumes when no other is named.", "none, because a One-off does not recur."]'::jsonb, 3, 'A One-off is due once. There is nothing to roll to and no period to step back through, so none is the correct answer after it is discharged.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 11, 'rollForward also returns none for the frequency Other. What does that none mean?', '["The obligation is finished, in the same way as a filed One-off.", "The obligation is Draft until a frequency from the list is chosen for it.", "The engine has no interval to step by, so somebody who knows the next date has to enter it.", "The engine rolls it by the default of one year once it is filed."]'::jsonb, 2, 'Other names no fixed interval, so rollForward returns none and supplies no next date. REG-2026-013, an Other obligation with no dates, reads No date set until somebody enters one.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 12, 'The waste consignment register carries the frequency Other and nothing in either date field. Before anyone can say it is late, what has to happen?', '["Somebody has to enter when it is due.", "It has to be filed once, so rollForward has a date to step on from.", "It must become a One-off.", "Nothing, because a row that reads No date set is never late."]'::jsonb, 0, 'It reads No date set, with the reason "No due date or expiry date has been set, so nothing can fall due." None tells the reader the schedule for this row is somebody''s job.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 13, 'REG-2026-006 and REG-2026-007 are both One-off obligations whose due dates have passed. What single field separates Compliant from Overdue?', '["The lead time: REG-2026-006 has one recorded and REG-2026-007 falls back on the default.", "The filing: REG-2026-006 was filed on 2026-08-10 and REG-2026-007 has none.", "The lifecycle: REG-2026-006 is Draft and REG-2026-007 is Active.", "The expiry: REG-2026-006 carries one and REG-2026-007 does not."]'::jsonb, 1, 'Both are Active, both are One-off and neither has an expiry. A passed due date with a filing discharges a One-off; with no filing it is Overdue, and REG-2026-007''s reason reads "The due date passed 44 days ago."'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 14, 'REG-2026-006 reads Compliant beside a negative days until. Which words in its reason tell a reader the status is not stale?', '["\"next due in\"", "\"was for an earlier period\"", "\"not tracked against a date\"", "\"nothing further is due\""]'::jsonb, 3, 'The reason reads "Filed 2026-08-10. A one-off obligation, nothing further is due." The obligation was met, it does not recur, and the passed date is the date it was met against.'),
  ('compliance', 'beginner', 'module', 'm04-rolling-the-schedule-forward', 15, 'Where do REG-2026-007 and REG-2026-006 sit in the register sorted worst first?', '["First and ninth.", "Third and eighth.", "Second and eighth.", "Second and ninth."]'::jsonb, 2, 'REG-2026-007 is second, straight after the expired licence. REG-2026-006 is eighth, among the Compliant rows. The filing is the one difference between them.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 1, 'documentControl.DOC_STATUSES holds seven words. Which of them does documentControl.EFFECTIVE_STATUSES treat as in force?', '["Published alone.", "Published, Approved and In Review.", "Published and Approved.", "Every status except Obsolete and Rejected."]'::jsonb, 2, 'EFFECTIVE_STATUSES holds Published and Approved, the two statuses a document carries once it has been signed off for people to work to. A document in any other status reads Not in force.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 2, 'HSE-PRO-0007 and OPS-PRO-0004 both have review dates behind the as-of date. HSE-PRO-0007 reads Review overdue and OPS-PRO-0004 reads Not in force. What separates them?', '["OPS-PRO-0004 is Superseded, a status outside EFFECTIVE_STATUSES, and reviewState reads only documents in force.", "OPS-PRO-0004''s review date, 2020-01-06, is too far back for the review window to reach.", "OPS-PRO-0004 is a Draft, and reviewState waits for a Draft to be published.", "HSE-PRO-0007 is a procedure, and only procedures are read against a review date."]'::jsonb, 0, 'The old custody metering procedure is Superseded and nobody works to it. Calling it Review overdue would put a dead document at the top of a live queue, so it reads Not in force whatever its date.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 3, 'OPS-PHI-0001, the flare management philosophy, is Published with no review date on the record. What review state does it read, and what does that ask of the document controller?', '["Not in force: withdraw it.", "Review overdue: review it now.", "Review scheduled: nothing yet, because an undated document is left to the default review period.", "No review scheduled: give it a review date."]'::jsonb, 3, 'A document in force with no review date is one nobody has committed to looking at again. The library shows it as its own state so it can be found and given a date.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 4, 'documentPrefix builds a document number prefix from a department and a category. What does it give for ''QA'' and ''ITP''?', '["QAI-ITP", "QA-ITP", "GEN-DOC", "QA-ITP-0001"]'::jsonb, 1, 'documentPrefix takes the first three letters of each, and two letters of ''QA'' stay two letters. GEN-DOC is what an empty department and category give.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 5, 'A document issued 2025-03-14 on a 24 month review period is corrected and re-published on 2026-10-01. When does Document Control put its review?', '["2028-10-01, counted from the correction.", "2026-10-01, the day the correction was re-published.", "2027-03-14, counted from the issue date.", "No date at all, because a re-published document starts with none."]'::jsonb, 2, 'nextReviewDate counts from the issue date. A correction is not the full review the period asks for, and if it reset the clock a document could be kept from review indefinitely.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 6, 'nextReviewDate is called for an issue date of 2025-03-14 with the review period missing, as null. What does it return, and whose job is the default?', '["No date. Applying DEFAULT_REVIEW_PERIOD_MONTHS is the caller''s job.", "2027-03-14, because the function applies DEFAULT_REVIEW_PERIOD_MONTHS itself.", "A refusal naming the missing review period as a required field.", "The issue date itself, so the document comes up for review at once."]'::jsonb, 0, 'The digest prints none for a period of null and for a period of 0. It prints 2027-03-14 only when the caller passes 24, DEFAULT_REVIEW_PERIOD_MONTHS. The owner''s recorded position is that the default is the caller''s to apply, and the course teaches it as a limit.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 7, 'nextRevisionNumber is given the current revision ''7''. What does it return?', '["''8''", "''07''", "''01''", "''08''"]'::jsonb, 3, 'A revision written with one digit comes back padded to two. Keeping the width keeps the text order and the number order the same, so ''09'' then ''10'' sorts correctly as text.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 8, 'nextRevisionNumber is given the letter ''A'', and separately null. What does it return for each?', '["''B'' for the letter and ''01'' for null.", "''01'' for both.", "A refusal for both.", "''02'' for both."]'::jsonb, 1, 'A revision that is not a number, whether a letter, an empty string or null, starts a numbered sequence at ''01'' because the engine has nothing it can count from. '' 04 '' with spaces around it gives ''05''.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 9, 'On revision rev-0019-10 of ENG-PRO-0019, authored by u-adaeze, the author assigns herself as reviewer. What does the engine answer?', '["REFUSED: Only the reviewer this task is assigned to can decide it.", "ALLOWED, with a warning recorded against the task.", "REFUSED: The author of a revision cannot review it. Choose somebody independent of the draft.", "REFUSED: Choose the reviewer."]'::jsonb, 2, 'This is the first of the two author checks, made at assignment. The rule is owner decision AS15 D1: a document review task is decided only by its assigned reviewer.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 10, 'No reviewer is chosen for the revision. What does the engine answer, and why does that refusal come before any decision?', '["ALLOWED, an empty field counts as independent.", "REFUSED: The author of a revision cannot review it, because an empty field defaults to the author.", "ALLOWED, the task falls to the document controller.", "REFUSED: Choose the reviewer. Nobody is named to check against the author."]'::jsonb, 3, 'The gate needs two named people on the record, the author and the reviewer. The engine will not treat an empty field as independent.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 11, 'The author was assigned as reviewer by mistake and now tries to decide the task. At which step is she stopped, and why?', '["At the decision, which is checked against the author as well.", "Nowhere, because the assignment made her the reviewer of the task.", "At assignment only, so the decision itself goes through.", "At the decision, because an approved task cannot be decided again."]'::jsonb, 0, 'The engine answers REFUSED: The author of a revision cannot approve it. A slip at assignment does not become an approval, which is why the rule is checked twice.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 12, 'Somebody other than the assigned reviewer, however senior, decides the task on the reviewer''s behalf. What does the engine answer?', '["ALLOWED, because the decider is not the author and so is independent of the draft.", "REFUSED: Only the reviewer this task is assigned to can decide it.", "REFUSED: The author of a revision cannot approve it.", "ALLOWED, once the assigned reviewer''s name is recorded beside the decision."]'::jsonb, 1, 'Independence from the author is not enough at the decision step. Only the reviewer the task is assigned to may decide it.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 13, 'EFFECTIVE_STATUSES treats two statuses as in force. Name the document in force that the published count of 3 leaves out.', '["OPS-PHI-0001, which summarise leaves out for having no review date.", "OPS-PLA-0002, which summarise moves to the review due soon count.", "HSE-PRO-0007, which summarise counts only under review overdue.", "ENG-STD-0011, the tank inspection standard, which is Approved."]'::jsonb, 3, 'EFFECTIVE_STATUSES holds Published and Approved. The status counts read Published 3 and Approved 1: the sampling procedure, the emergency response plan and the flare philosophy are Published, and the tank inspection standard is Approved.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 14, 'byReviewUrgency places OPS-PHI-0001, which has no review date, fourth in the queue. Why does it sit above every document that is not in force?', '["Undated documents go first within the queue, so the missing date lifts it.", "It is Published, and Published documents always sort above Approved and Draft ones.", "Review states decide the order first, and No review scheduled comes before Not in force.", "Its number sorts ahead of the three documents below it."]'::jsonb, 2, 'The review states come first in the order Review overdue, Review due soon, Review scheduled, No review scheduled and then Not in force. Within a state the nearest date comes first and undated documents go last.'),
  ('compliance', 'beginner', 'module', 'm05-controlled-documents', 15, 'OPS-PRO-0004 carries the oldest review date in the library, 2020-01-06, at -2474 days. Where does it sit in byReviewUrgency, and why?', '["First, because the most passed review date in the library is the most urgent one.", "Fifth, first of the three not in force, because it is the only one of them with a review date.", "Seventh, because a Superseded document is always the last row of the queue.", "Fourth, because its passed date lifts it above the one undated document in force."]'::jsonb, 1, 'Its review state is Not in force, so a passed date does not raise it above any document in force. Among the three not in force, the nearest review date comes first and undated documents go last.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 1, 'summarise prints an attention count of 5 for the IKORO register at 2026-10-15. Which five obligations are behind it?', '["REG-2026-005, REG-2026-007, REG-2026-002, REG-2026-012 and REG-2026-013.", "REG-2026-005, REG-2026-007, REG-2026-002, REG-2026-012 and REG-2026-001.", "REG-2026-005, REG-2026-007, REG-2026-002, REG-2026-003 and REG-2026-001.", "REG-2026-007, REG-2026-002, REG-2026-012, REG-2026-001 and REG-2026-003."]'::jsonb, 1, 'The attention statuses are Expired, Overdue and Due soon: the licence, the notification and the water quality return, then the rental and the discharge permit. REG-2026-013 reads No date set and REG-2026-003 reads On track.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 2, 'countBy regime prints Environmental 5. What does that count tell a compliance lead?', '["That five Environmental rows need action now.", "That five Environmental obligations are Active and counted down against their dates at 2026-10-15.", "That the Environmental regime holds five of the thirteen permits, with the rest spread across other regimes.", "The shape of the register, including rows it is not counting down."]'::jsonb, 3, 'The five Environmental rows include REG-2026-009, which is Superseded, and REG-2026-011, which is Not applicable. A regime count is the shape of the register and says nothing about live work.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Reading the whole register, the discharge permit REG-2026-001 is Due soon with a next action date of 2026-11-20. Which of its dates is that, and what would a reader who counted to the other one miss?', '["The expiry. A reader counting to the due date of 2027-03-31 would miss the permit lapsing.", "The due date. A reader counting to the expiry would see a lapse that the renewal has already covered.", "The due date rolled forward. A reader counting to the expiry would miss the next filing.", "The expiry. A reader counting to the due date would read the same status, so nothing is missed."]'::jsonb, 0, 'Read end to end, the permit''s row shows 2026-11-20 as its next action date. Counting to 2027-03-31 would give a reader the picture REG-2026-004 shows for the same date: On track.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 4, 'The flare return REG-2026-003 and the monitoring report REG-2026-004 both read On track. What do their last filings have in common?', '["Each counts for this period.", "Each was filed late.", "Each belongs to an earlier period.", "Each is too old for the engine to read, so it is treated as missing."]'::jsonb, 2, 'The flare return was filed 2026-07-28 before a period starting 2026-07-31. The monitoring report was filed 2026-03-30, one day before its period starts on 2026-03-31. The work for the current period is still to do.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 5, 'Reading the IKORO library at 2026-10-15, which three actions does it ask of a document controller?', '["Review HSE-PRO-0007, review OPS-PRO-0004, and give OPS-PHI-0001 a review date.", "Review HSE-PRO-0007, start the review of OPS-PLA-0002, and give OPS-PHI-0001 a review date.", "Review HSE-PRO-0007, start the review of OPS-PLA-0002, and review ENG-STD-0011.", "Start the review of OPS-PLA-0002, publish HSE-PRO-0012, and decide ENG-PRO-0019."]'::jsonb, 1, 'The sampling procedure is Review overdue, the emergency response plan Review due soon, and the flare philosophy No review scheduled. OPS-PHI-0001 has no issue date recorded, so nextReviewDate has nothing to count a period from. OPS-PRO-0004 is Not in force and ENG-STD-0011 is Review scheduled at 258 days.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 6, 'The register and the library each show a missing date as a state of its own. Which pair of words is that?', '["Draft and Not in force.", "Not applicable and Review scheduled.", "Overdue and Review overdue.", "No date set and No review scheduled."]'::jsonb, 3, 'REG-2026-013 has no due date and no expiry and reads No date set. OPS-PHI-0001 is in force with no review date and reads No review scheduled. In both, the gap is visible instead of hidden.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 7, 'A Superseded obligation and a Superseded document are both on IKORO''s books. What does each read?', '["The obligation reads Superseded, and the document reads Not in force.", "Both read Superseded, the lifecycle word they share.", "The obligation reads Overdue, because its passed due date is still on the record, and the document reads Not in force.", "The obligation reads Not applicable, and the document reads Review overdue."]'::jsonb, 0, 'REG-2026-009 reads Superseded and is not counted down. OPS-PRO-0004 is Superseded and its review state is Not in force. In both apps a record that is not live does not drive a warning.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 8, 'ENG-STD-0011, the tank inspection standard, is Approved with its next review on 2027-06-30. What review state does it read at 2026-10-15, and why?', '["Not in force, because only a Published document is read for review.", "Review due soon, because an Approved document is reviewed before publication.", "Review scheduled, because Approved is a status in force.", "No review scheduled, because it has no issue date to count from."]'::jsonb, 2, 'EFFECTIVE_STATUSES holds Published and Approved, so reviewState reads the standard, and at 258 days it reads Review scheduled. Its issue date, 2025-06-30, is on the record, and nextReviewDate from it agrees with the recorded review date.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 9, 'The emergency response plan OPS-PLA-0002 is corrected and re-published before its review date of 2026-11-02. What happens to that date?', '["It moves to 12 months after the correction.", "It does not move.", "It moves to the day of the correction.", "It is cleared, so the plan reads No review scheduled."]'::jsonb, 1, 'A review date is earned at issue. OPS-PLA-0002 was issued 2025-11-02 on a 12 month period, and a correction does not reset the clock.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 10, 'The next tier reads an inspection and test plan. Which point type does qualityAssurance.BLOCKING_POINT_TYPES hold?', '["Hold point and Witness point.", "Witness point alone.", "Every one of the five types.", "Hold point alone."]'::jsonb, 3, 'A hold point stops work until it is released. POINT_TYPES lists five: Hold point, Witness point, Review point, Monitor point and Surveillance point.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 11, 'The next tier''s NCRs each carry a severity. Which list does qualityAssurance.NCR_SEVERITIES hold?', '["Critical, Major, Minor, Observation", "Critical, Major, Minor", "Conformant, Nonconformant, Observation and Not applicable", "Expired, Overdue, Due soon"]'::jsonb, 0, 'Critical, Major and Minor leaves out Observation, which the list holds. Conformant, Nonconformant, Observation and Not applicable are the checklist answers in auditManagement.ANSWERED_RESULTS.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 12, 'This tier names three ideas that carry forward into every app the course teaches. Which three?', '["The as-of date is the machine''s clock, a status is derived, and a gate refuses.", "The as-of date is an input, a status is typed by its owner, and a gate warns.", "The as-of date is an input, a status is derived, and a gate refuses until the record is complete.", "The as-of date is an input, a status is derived, and a gate flags for later."]'::jsonb, 2, 'In Document Control the gate asked for a named reviewer other than the author and refused until it had one. The next tier is full of gates of that kind, each asking for evidence, a date or a named person.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 13, 'The rule that the author does not review a revision reappears in the next two tiers. What does it become there, and where are the approval rules for management of change taught?', '["An inspector may not inspect their own weld; they are taught in this course''s Expert tier.", "An auditor may not audit their own area; management of change approvals belong to Risk, Change & Learning.", "An auditor may not audit their own area; management of change approvals are taught in this course''s next tier.", "A reviewer may not review twice in a year; they belong to Risk, Change & Learning."]'::jsonb, 1, 'Independence runs through the next two tiers as the auditor rule. Risk scores, heat maps and the approval rules for management of change belong to the sibling course.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 14, 'countBy regime prints Reporting 3. Which three obligations are they?', '["REG-2026-002, REG-2026-003 and REG-2026-008.", "REG-2026-002, REG-2026-003 and REG-2026-004.", "REG-2026-003, REG-2026-004 and REG-2026-008.", "REG-2026-002, REG-2026-008 and REG-2026-010."]'::jsonb, 0, 'The water quality return, the flare return and the community report are Reporting. REG-2026-004 is Environmental and REG-2026-010 is Health & Safety, though both are periodic reports by type.'),
  ('compliance', 'beginner', 'module', 'm06-the-associate-reading', 15, 'REG-2026-013 has no dates and sits tenth in the sorted register. REG-2026-010 has a due date of 2027-06-30 and sits eleventh. Why is the undated row higher?', '["Undated rows always sort above dated ones within the bottom half of the register.", "REG-2026-010''s due date is so far ahead that the engine sorts it below the undated row.", "No date set ranks sixth and Draft seventh in STATUS_SEVERITY, which byUrgency reads first.", "REG-2026-013 is Environmental and REG-2026-010 is Health & Safety, and the register groups by regime."]'::jsonb, 2, 'STATUS_SEVERITY runs No date set sixth and Draft seventh. byUrgency sorts by status first, and puts undated rows last only among rows with the same status.'),
  ('compliance', 'beginner', 'final', null, 1, 'One module''s row in the export table reads 5 exported functions, 1 exported list or constant, and 1 export that reads a date against today. Which module is it?', '["complianceStatus", "documentControl", "calendar", "auditManagement"]'::jsonb, 2, 'The calendar sits under all five apps. complianceStatus reads 11, 8 and 4, documentControl 14, 7 and 4, and auditManagement 4 that read a date.'),
  ('compliance', 'beginner', 'final', null, 2, 'Of these four inputs, which one does parseDateOnly read as a real day?', '["2027-02-28, which daysUntil counts as 136.", "2026-13-01, as the next year''s first day.", "2026-02-30, rolled into March.", "tbc, read as the as-of date until a date is confirmed."]'::jsonb, 0, '2026-13-01 names a thirteenth month and 2026-02-30 a day February does not have, so both print null. tbc is no date. The calendar refuses instead of guessing.'),
  ('compliance', 'beginner', 'final', null, 3, 'When the date passed as today cannot be read, the register refuses while the library answers Review scheduled for a published document whose review date is 2020-01-06. Why the two behaviours?', '["The library reads its own clock instead.", "Review scheduled is the library''s refusal.", "Old review dates are exempt from the check.", "Only deriveStatus refuses an unreadable today, which is AS15 Q1."]'::jsonb, 3, 'The register''s refusal is the RangeError deriveStatus throws. The library''s Review scheduled is an answer given as though nothing were due, a held limit of the digest, and it says nothing about the document.'),
  ('compliance', 'beginner', 'final', null, 4, 'Remove the expiry from REG-2026-005, the radioactive source licence, and change nothing else. What does it read?', '["Expired, as before the field was removed.", "On track, counted to its due date of 2026-12-31.", "No date set, because a licence with no expiry has no date to count.", "Overdue, counted to the old expiry."]'::jsonb, 1, 'With the expiry removed the due date of 2026-12-31 is the next action date. It is ahead and outside the window, so the licence reads On track, the same as with the expiry moved to 2027-09-30.'),
  ('compliance', 'beginner', 'final', null, 5, 'In complianceStatus.STATUS_SEVERITY, which status sits immediately below Draft?', '["Not applicable", "No date set", "Superseded", "Compliant"]'::jsonb, 2, 'The list runs Expired, Overdue, Due soon, On track, Compliant, No date set, Draft, Superseded and Not applicable. Draft is seventh and Superseded eighth.'),
  ('compliance', 'beginner', 'final', null, 6, 'REG-2026-011, the night noise permit, has a due date of 2026-05-01 that has passed, and its lifecycle reads Not applicable. What status does the register show?', '["Not applicable", "Overdue", "Expired", "No date set"]'::jsonb, 0, 'For Draft, Superseded and Not applicable the lifecycle is the status. The permit does not bind this operator, so its passed date prints a day count and drives no warning.'),
  ('compliance', 'beginner', 'final', null, 7, 'REG-2026-010, the safety case resubmission, has a due date of 2027-06-30 and reads Draft. What does the Draft lifecycle mean for the row?', '["It is due in 258 days and will turn On track.", "It has been replaced by another obligation.", "It does not bind the operator.", "It is still being set up, so nobody is warned about it."]'::jsonb, 3, 'A Draft is a record not yet in force, so warning anyone about it would be wrong. An obligation replaced by another is Superseded; one that does not bind the operator is Not applicable.'),
  ('compliance', 'beginner', 'final', null, 8, 'REG-2026-012 and REG-2026-001 are both Due soon. Which sorts first in byUrgency, and why?', '["REG-2026-001, an expiry outranks a due date.", "REG-2026-012, whose 2026-11-09 comes before 2026-11-20.", "REG-2026-001, because a lead time set on the record outranks the default.", "REG-2026-012, Financial sorts above Environmental."]'::jsonb, 1, 'Both carry the same status, so byUrgency sorts them by the nearest next action date: 2026-11-09 for the rental and 2026-11-20 for the permit. They sit fourth and fifth.'),
  ('compliance', 'beginner', 'final', null, 9, 'REG-2026-003 is due 16 days after the as-of date. Of these lead times, which leaves it On track?', '["17", "90", "7", "null"]'::jsonb, 2, 'The table prints 0, 7, 14 and 15 as On track. 17 and 90 reach the 16 days that remain, and null is replaced by the default window, so all three read Due soon.'),
  ('compliance', 'beginner', 'final', null, 10, 'The flare return''s lead time field holds an empty string. What does the return read?', '["Due soon, the same as with no lead time set at all.", "On track, an empty field opens no window.", "On track, as with its recorded 14.", "Overdue, an empty field reads as zero."]'::jsonb, 0, 'An empty string is not a usable lead time, so the engine applies DEFAULT_LEAD_TIME_DAYS. The digest prints '''' (empty) as Due soon, beside null, -5, ''ten'' and a field left out.'),
  ('compliance', 'beginner', 'final', null, 11, 'An Annual and a Biennial obligation both fall due 2026-10-31. On which dates do their current periods begin?', '["2026-04-30 and 2025-10-31, a half year and a year back.", "2026-07-31 and 2026-04-30, a quarter and a half year back.", "2026-09-30 and 2025-10-31, a month and a year back.", "2025-10-31 and 2024-10-31."]'::jsonb, 3, 'periodStart steps one frequency back from the next due date. October has a thirty-first, so neither start is pulled back: Annual reads 2025-10-31 at -349 days and Biennial 2024-10-31 at -714.'),
  ('compliance', 'beginner', 'final', null, 12, 'summarise prints in review 1 for the IKORO library. Which document is it?', '["HSE-PRO-0012, the draft.", "ENG-PRO-0019, the hydrotest procedure.", "OPS-PLA-0002, the terminal emergency response plan.", "OPS-PHI-0001, the philosophy."]'::jsonb, 1, 'ENG-PRO-0019 is the one document with the status In Review, and its revision rev-0019-10 carries the reviewer rule. HSE-PRO-0012 is a Draft, and OPS-PLA-0002 is Published and reads Review due soon.'),
  ('compliance', 'beginner', 'final', null, 13, 'After the late filing of REG-2026-002 is recorded, rollForward moves its due date from 2026-10-10 to 2026-11-10. Why does the filing on 2026-10-14 count for the new period?', '["The filing is within a month of the old due date, and any filing in that month counts.", "Its periodStart is 2026-10-14, the filing date.", "The rolled row''s periodStart is 2026-10-10, and the filing is on or after it.", "Any filing recorded after a due date is carried into the period that follows it."]'::jsonb, 2, 'This joins the current period rule and the roll. Stepping one month back from 2026-11-10 gives 2026-10-10, so a filing dated 2026-10-14 falls inside the period and counts.'),
  ('compliance', 'beginner', 'final', null, 14, 'A quarterly obligation last due on 2026-08-31 is rolled on. Where does it land, and how many days from the as-of date?', '["2026-11-30, 46 days ahead.", "2026-11-30, 136 days ahead.", "2026-10-31, 16 days ahead.", "2027-02-28, 136 days ahead."]'::jsonb, 0, 'November has thirty days, so the date is pulled back to 2026-11-30, which daysUntil counts as 46. 2027-02-28 at 136 is the Semi-annual roll.'),
  ('compliance', 'beginner', 'final', null, 15, 'The date 2026-09-30 appears in both the rollForward table and the periodStart table. Which two calls produce it?', '["The Quarterly roll from 2026-08-31, and the Quarterly period start for 2026-10-31.", "The Monthly roll from 2026-08-31, and the Semi-annual period start for 2026-10-31.", "The Semi-annual roll from 2026-08-31, and the Monthly period start for 2026-10-31.", "The Monthly roll from 2026-08-31, and the Monthly period start for 2026-10-31."]'::jsonb, 3, 'rollForward steps forward from a due date and periodStart steps back from one, and both pull a thirty-first back when the month is shorter. The Semi-annual roll from 2026-03-31 lands there too.'),
  ('compliance', 'beginner', 'final', null, 16, 'Which app holds audits, checklists, findings and audit programmes, and which engine module backs it?', '["ISO Compliance, backed by isoCompliance.", "The Audit & Findings Manager, backed by auditManagement.", "Quality Assurance Plan & NCR, backed by qualityAssurance.", "Document Control, backed by documentControl."]'::jsonb, 1, 'Each of the five apps is backed by one module, with the calendar under all of them. ISO Compliance holds a clause register for a standard, and the Quality Assurance Plan & NCR app holds inspection and test plans and NCRs.'),
  ('compliance', 'beginner', 'final', null, 17, 'Which next due date, and which day count, does the digest print for the Biennial roll from 2026-08-31?', '["2028-08-31, 320 days ahead.", "2027-08-31, 686 days ahead.", "2028-08-31, 686 days ahead.", "2028-02-29, 686 days ahead."]'::jsonb, 2, 'Biennial steps two years and August keeps its thirty-first. 2027-08-31 at 320 days is the Annual roll.'),
  ('compliance', 'beginner', 'final', null, 18, 'The month end rule works in three places across these apps. A document issued on 2024-02-29 on a 12 month review period comes up for review when?', '["2025-02-28, pulled back the same way rollForward pulls a due date back.", "2026-02-28, pushed a further year on because February 2025 has no twenty-ninth.", "2024-02-29, the issue date, because a leap day cannot be rolled.", "No date, because nextReviewDate refuses to count from a leap day."]'::jsonb, 0, 'nextReviewDate prints 2025-02-28 at -594 days. rollForward does the same to 2028-02-29 rolled Annual, giving 2029-02-28, so a due date, its period and a review date agree about month ends.'),
  ('compliance', 'beginner', 'final', null, 19, 'A semi-annual schedule is rolled from 2026-08-31 to 2027-02-28. Where does the following semi-annual roll land?', '["2027-08-31", "2027-02-28", "2028-08-31", "2027-08-28"]'::jsonb, 3, 'The digest prints 2026-08-31, 2027-02-28 and then 2027-08-28 for Semi-annual. The second step starts from the twenty-eighth it landed on in February. 2027-08-31 is the Annual roll from 2026-08-31, 2028-08-31 the Biennial one, and 2027-02-28 is the first step itself.'),
  ('compliance', 'beginner', 'final', null, 20, 'A department ''Operations'' files a ''Plan''. Which document number prefix comes back?', '["OPS-PLA", "OPE-PLA", "OP-PL", "GEN-DOC"]'::jsonb, 1, 'documentPrefix takes the first three letters of each. OPS-PLA-0002 is a number as it stands in the library, and the digest does not say how it was issued. GEN-DOC is what an empty department and category give.'),
  ('compliance', 'beginner', 'final', null, 21, 'atLeastConfidential is read against the default floor Confidential. What does it answer for Internal and for Restricted?', '["true for both, because each is a restricted class.", "true for Internal only.", "false for Internal and true for Restricted.", "false for both, because only Confidential meets the floor."]'::jsonb, 2, 'atLeastConfidential answers true at the floor or above it. The digest prints Public false, Internal false, Confidential true and Restricted true.'),
  ('compliance', 'beginner', 'final', null, 22, 'Two issue dates, each with its own review period, are sent by nextReviewDate to the same review date of 2026-02-28. Which two?', '["2024-08-31 on 18 months, and 2025-12-31 on 2 months.", "2024-08-31 on 18 months, and 2024-02-29 on 12 months.", "2025-12-31 on 2 months, and 2025-11-02 on 12 months.", "2024-02-29 on 12 months, and 2025-06-30 on 24 months."]'::jsonb, 0, 'Both land on the last day of February, which has no thirty-first, at -229 days. 2024-02-29 on 12 months gives 2025-02-28, and 2025-11-02 on 12 months gives 2026-11-02.'),
  ('compliance', 'beginner', 'final', null, 23, 'A review period of 0 months is passed with the issue date 2025-03-14. What comes back from nextReviewDate?', '["2025-03-14, the issue date itself", "2027-03-14, from the default", "A refusal naming the period", "none"]'::jsonb, 3, 'A period of 0 returns none, and so does a period of null. 2027-03-14 appears only when the caller passes DEFAULT_REVIEW_PERIOD_MONTHS, and the default is the caller''s to apply.'),
  ('compliance', 'beginner', 'final', null, 24, 'A review task on rev-0019-10 has already been approved, and somebody decides it again. What does the engine answer?', '["ALLOWED, as a second approval.", "REFUSED: This review task is already approved.", "REFUSED: Only the reviewer this task is assigned to can decide it.", "ALLOWED, provided the decision is made by the assigned reviewer."]'::jsonb, 1, 'An approval on the record stays the approval that was given, so a second decision on the same task is refused.'),
  ('compliance', 'beginner', 'final', null, 25, 'Which two of the seven requests on rev-0019-10 does the engine allow?', '["An independent reviewer is assigned; somebody else decides it for the reviewer.", "The author assigns herself; the assigned reviewer decides a pending task.", "An independent reviewer is assigned; the assigned reviewer decides a pending task.", "No reviewer is chosen; the assigned reviewer decides a pending task."]'::jsonb, 2, 'Both allowed requests have two named people on the record who are different. The author assigning herself, no reviewer, a stand-in decider, the author deciding and a second decision are refused.'),
  ('compliance', 'beginner', 'final', null, 26, 'nextRevisionNumber is given '' 04 '', with spaces around it. What does it return?', '["''05''", "'' 05 ''", "''5''", "''01''"]'::jsonb, 0, 'The spaces are ignored and the number inside is read, and the width of two digits is kept. ''01'' is what a revision that is not a number gives.'),
  ('compliance', 'beginner', 'final', null, 27, 'summarise over the 7 IKORO documents counts Obsolete 0 and Rejected 0. What does printing those zeros tell the reader?', '["The two statuses are switched off in this library.", "The engine could not read those statuses, so it printed a placeholder.", "Obsolete and Rejected documents are kept in a separate archive that summarise does not see.", "They were counted, and none were found."]'::jsonb, 3, 'A zero printed beside a status is a finding in its own right. The library''s counts read Draft 1, In Review 1, Approved 1, Published 3, Superseded 1, Obsolete 0 and Rejected 0.'),
  ('compliance', 'beginner', 'final', null, 28, 'A caller passes DEFAULT_REVIEW_PERIOD_MONTHS for a document issued 2025-03-14. What review date comes back?', '["2028-10-01", "2027-03-14", "2026-10-01", "none"]'::jsonb, 1, 'DEFAULT_REVIEW_PERIOD_MONTHS is 24, and 24 months on from 2025-03-14 is 2027-03-14, 150 days from the as-of date. 2028-10-01 is what counting from a correction would give.'),
  ('compliance', 'beginner', 'final', null, 29, 'HSE-PRO-0007 was issued 2024-09-30 on a 24 month period. Its recorded next review is 2026-09-30. What does the digest''s recomputation show?', '["The recomputed date disagrees and the record has to be corrected.", "Nothing, an overdue document is left out.", "The recomputed date agrees with the one on record: true.", "The recomputed date agrees only once the default period is applied."]'::jsonb, 2, 'nextReviewDate from 2024-09-30 on 24 months gives 2026-09-30, and the digest prints true for the two agreeing. OPS-PLA-0002 and ENG-STD-0011 agree as well.'),
  ('compliance', 'beginner', 'final', null, 30, 'Why can nextReviewDate give OPS-PHI-0001, the flare management philosophy, no review date?', '["Its review period is 0.", "It is not in force.", "Philosophies are exempt from review.", "It has no issue date on the record to count from."]'::jsonb, 3, 'The digest names four documents with no issue date recorded: OPS-PHI-0001, OPS-PRO-0004, HSE-PRO-0012 and ENG-PRO-0019. OPS-PHI-0001 is Published and in force, and reads No review scheduled.'),
  ('compliance', 'beginner', 'final', null, 31, 'byUrgency sorts the register and byReviewUrgency sorts the library. Which rule do the two sorts share?', '["The state comes first, then the nearest date, and undated records go last.", "The nearest date comes first, whatever the state, and undated records go first.", "The code or document number decides, and the state only breaks ties.", "The oldest record comes first, because it has waited longest for attention."]'::jsonb, 0, 'In both, the states that need action lead the list and records that are not live go to the bottom. A reader who has learned one sort can read the other.'),
  ('compliance', 'beginner', 'final', null, 32, 'An obligation can carry its own lead time. What sets the width of the Review due soon window for a controlled document?', '["Each document''s own lead time, or the default.", "One constant for the module, documentControl.REVIEW_LEAD_DAYS.", "The review period in months, read as days.", "DEFAULT_REVIEW_PERIOD_MONTHS, in days."]'::jsonb, 1, 'The register reads each obligation''s lead time and falls back on DEFAULT_LEAD_TIME_DAYS. The library''s window is REVIEW_LEAD_DAYS, and OPS-PLA-0002 at 18 days reads Review due soon.'),
  ('compliance', 'beginner', 'final', null, 33, 'REG-2026-013 carries the frequency Other and has no dates. What do rollForward and the register give it?', '["The date one year on, and On track.", "A refusal, and Draft until a date is entered.", "No next date, and Overdue since nothing was filed.", "No next date from rollForward, and No date set on the register."]'::jsonb, 3, 'Other names no interval, so rollForward gives none. With no due date and no expiry the status is No date set, and somebody who knows the date has to enter it.'),
  ('compliance', 'beginner', 'final', null, 34, 'Two Compliant reasons are "Last filed 2026-08-05, next due in" a number of days, and "Filed 2026-08-10. A one-off obligation, nothing further is due." Which obligations give them?', '["REG-2026-006 gives the first and REG-2026-008 the second.", "REG-2026-003 gives the first and REG-2026-006 the second.", "REG-2026-008 gives the first and REG-2026-006 the second.", "REG-2026-008 gives the first and REG-2026-007 the second."]'::jsonb, 2, 'The community report has a filing inside its current period and a next due date. The right of way consent is a filed One-off, which rollForward cannot move on, so nothing further is due.'),
  ('compliance', 'beginner', 'final', null, 35, 'Two regimes hold a single IKORO obligation each, Financial and Licensing. Name the obligation in each.', '["The concession rental is Financial; the radioactive source licence is Licensing.", "The radioactive source licence is Financial; the concession rental is Licensing.", "The concession rental is Financial; the right of way consent is Licensing.", "The discharge permit is Financial; the radioactive source licence is Licensing."]'::jsonb, 0, 'REG-2026-012, the concession rental, is Financial, a Fee or levy. REG-2026-005, the radioactive source licence, is Licensing, a Licence. The right of way consent is Operational and the discharge permit is Environmental.'),
  ('compliance', 'beginner', 'final', null, 36, 'What obligation type does the regime table give REG-2026-007, the oil spill contingency plan notification?', '["Consent", "Periodic report", "Permit", "Notification"]'::jsonb, 3, 'REG-2026-007 is Health & Safety by regime and Notification by type. Consent is the right of way consent''s type.'),
  ('compliance', 'beginner', 'final', null, 37, 'Why does every status and day count in this tier carry the as-of date 2026-10-15 beside it?', '["It is the date the IKORO records were last edited by hand.", "Each is derived against that date and is true at no other.", "It is the date the regulator fixed for every return in the register.", "It is the date the machine clock read when the digest was built, which the engine records."]'::jsonb, 1, 'Move the as-of date and the same record reads differently with nobody having edited it. The digest never read the machine clock.'),
  ('compliance', 'beginner', 'final', null, 38, 'The monthly water quality return is filed late and rolled on. Of the summarise counts, which one loses it?', '["Due soon", "Compliant", "Overdue", "Expired"]'::jsonb, 2, 'As recorded it reads Overdue. After the filing and the roll the digest prints status Due soon, so it leaves Overdue and joins Due soon, which is still an attention status.'),
  ('compliance', 'beginner', 'final', null, 39, 'REG-2026-003 is given a lead time of 16 in place of its recorded 14. Which summarise count loses it?', '["On track", "Due soon", "Compliant", "Overdue"]'::jsonb, 0, 'With 14 it reads On track and with 16 it reads Due soon, so it leaves On track and joins Due soon, one of the attention statuses.'),
  ('compliance', 'beginner', 'final', null, 40, 'HSE-PRO-0012, the oily waste handling procedure, is a Draft with no review date. Where does it sit in the review queue?', '["Fourth, as No review scheduled, above every document not in force.", "First, because a Draft with no review date is the most urgent gap.", "Seventh, below the hydrotest procedure that is In Review.", "Sixth: Not in force and undated."]'::jsonb, 3, 'Draft is outside EFFECTIVE_STATUSES, so its state is Not in force. Among the three not in force, OPS-PRO-0004 comes first because it has a review date, then HSE-PRO-0012 and ENG-PRO-0019.'),
  ('compliance', 'beginner', 'final', null, 41, 'The next tier''s checklists record an answer for each item. Which list is auditManagement.ANSWERED_RESULTS?', '["Passed, Failed, Waived and Not applicable", "Conformant, Nonconformant, Observation and Not applicable", "Critical, Major, Minor, Observation", "Hold point, Witness point, Review point"]'::jsonb, 1, 'Critical, Major, Minor and Observation are the NCR severities. The Hold, Witness and Review points are three of the five point types.'),
  ('compliance', 'beginner', 'final', null, 42, 'REG-2026-002''s reason reads "The due date passed 5 days ago." What days until does the register print beside it?', '["5", "-15", "-5", "-14"]'::jsonb, 2, 'A passed date is a negative count, and the reason says it in words. -15 is the expired licence and -14 is the licence varied to a due date of 2026-10-01.');
